test("bulk redate scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-A", "3");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "grace-days", "3");
  await ui.setSetting(pg_uma, "note-threshold", "2.50");
  await ui.setSetting(pg_uma, "grace-C", "2");
  await ui.setSetting(pg_uma, "fiscal-start-month", "4");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "contact": " Ada@x ", "tags": "b, a"}));
  const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "12.50", "start": "2026-02-20", "end": "2026-04-30", "day": "31"}));
  expect(await ui.addPatron(pg_uma, p_ada, "Cam")).toBe(true);
  expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
  expect(await ui.statementAsOf(pg_uma, p_ada, "2026-02-10")).toBe(false);
  await ui.setToday(pg_uma, "2026-04-10");
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.generatePlans(pg_uma)).toBe(2);
  const c_cam_0 = await ui.claimAt(pg_uma, p_cam, 0);
  const c_cam_1 = await ui.claimAt(pg_uma, p_cam, 1);
  expect(await ui.addProof(pg_uma, c_cam_0)).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.claimAction(pg_uma, c_cam_1, "open")).toBe(true);
  expect(await ui.statementAsOf(pg_uma, p_ada, "2026-02-10")).toBe(false);
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimAction(pg_vic, c_cam_0, "settle")).toBe(true);
  await ui.sortBy(pg_vic, "grade");
  expect(await ui.claimAction(pg_vic, c_cam_1, "void")).toBe(true);
  expect(await ui.editPerson(pg_vic, p_ada, {"terms": "3"})).toBe(true);
  await ui.refresh(pg_vic);
  expect(await ui.addAlias(pg_vic, p_ada, "Bee")).toBe(true);
  expect(await ui.addHoliday(pg_vic, "2026-03-18")).toBe(true);
  await ui.setToday(pg_vic, "2026-04-20");
  await ui.setToday(pg_vic, "2026-05-20");
  await ui.setAsOf(pg_vic, "2026-03-05");
  await ui.refresh(pg_vic);
  await ui.expectAudit(sheet, [
  await ui.expectAudit(sheet, [
    `ROLE_SET sheet=${sheet} by=uma user=wes role=steward`,
